import React, { useState, useMemo } from 'react';
import { 
  Trash2, Plus, Play, Clock, Calendar, ShieldCheck, Globe, Home, BookOpen, RefreshCw, CheckCircle2, AlertCircle, Settings2, Users, FileText, MapPin
} from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import ScheduleGenerator from './ScheduleGenerator';
import GlobalOverview from './GlobalOverview';

const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  return `${String(h + hours).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, onDeleteDept, onClearSchedule, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [generationErrors, setGenerationErrors] = useState([]);
  const [currentVersion, setCurrentVersion] = useState("V1");
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- PDF GENERATION ENGINE ---
  const handleExportPDF = (row) => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    // Header Title (e.g., BSIS SECOND YEAR)
    doc.setFillColor(200, 200, 200);
    doc.rect(10, 10, pageWidth - 20, 15, 'F');
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    const title = `${deptName} YEAR ${row.year}`.toUpperCase();
    doc.text(title, pageWidth / 2, 20, { align: 'center' });

    // Table Data Preparation
    const tableRows = row.subs.map(s => [
      s.code,
      row.proctor.toUpperCase(),
      new Date(row.date).toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase(),
      s.slot.replace(/\s/g, '')
    ]);

    autoTable(doc, {
      startY: 25,
      head: [['CODE', 'Faculty In-Charged', 'Day', 'Time']],
      body: tableRows,
      theme: 'grid',
      headStyles: { 
        fillColor: [255, 255, 0], 
        textColor: [0, 0, 0], 
        fontStyle: 'bold', 
        halign: 'center',
        lineWidth: 0.1,
        lineColor: [0, 0, 0]
      },
      styles: { 
        fontSize: 10, 
        cellPadding: 4, 
        halign: 'center', 
        valign: 'middle',
        textColor: [0, 0, 0],
        lineWidth: 0.1,
        lineColor: [0, 0, 0]
      },
      didParseCell: function(data) {
        if (data.section === 'body') {
          const dayCell = data.row.cells[2].text[0];
          if (dayCell === 'THU') data.cell.styles.fillColor = [200, 230, 201];
          if (dayCell === 'FRI') data.cell.styles.fillColor = [255, 236, 179];
        }
      }
    });

    const finalY = doc.lastAutoTable.finalY + 10;
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text("Nothing Follows", pageWidth / 2, finalY, { align: 'center' });

    doc.save(`${row.section}_Exam_Slip.pdf`);
  };

  const consolidatedPreview = useMemo(() => {
    const deptData = globalSchedule.filter(s => s.dept_code === deptCode);
    const groups = {};
    const today = new Date().toISOString().split('T')[0];

    deptData.forEach(item => {
      const groupKey = `${item.section}-${item.exam_date}-${item.room}-${item.proctor}`;
      if (!groups[groupKey]) {
        groups[groupKey] = {
          section: item.section, date: item.exam_date, year: item.year_level, room: item.room,
          proctor: item.proctor, status: item.exam_date < today ? 'DONE' : (item.status || 'COMMITTED'),
          startTime: item.start_time, endTime: item.end_time, subs: []
        };
      }
      groups[groupKey].subs.push({ 
        code: item.subject_code, 
        name: item.subject_name, 
        slot: `${formatTime(item.start_time)} - ${formatTime(item.end_time)}`, 
        startTime: item.start_time 
      });
    });

    return Object.values(groups).map(g => ({ ...g, subs: g.subs.sort((a, b) => a.startTime.localeCompare(b.startTime)) }))
                 .sort((a, b) => new Date(a.date) - new Date(b.date) || a.section.localeCompare(b.section));
  }, [globalSchedule, deptCode]);

  const tablesByYearAndDay = useMemo(() => {
    const data = {};
    consolidatedPreview.forEach(item => {
      if (!data[item.year]) data[item.year] = {};
      if (!data[item.year][item.date]) data[item.year][item.date] = [];
      data[item.year][item.date].push(item);
    });
    return data;
  }, [consolidatedPreview]);

  // Form States
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const handleGenerateClick = () => {
    setGenerationErrors([]);
    const errors = [];
    const yearSubs = subjects[selectedYear] || [];

    if (yearSubs.length === 0) errors.push({ issue: "Subject Exhaustion", resolution: `Add subjects for Year ${selectedYear}.` });
    if (examDays === 0 || sectionCount === 0) errors.push({ issue: "Invalid Parameters", resolution: "Define total exam days and section capacity." });
    if (examDates.some(d => !d)) errors.push({ issue: "Timeline Incomplete", resolution: "Assign specific dates." });

    if (errors.length > 0) { setGenerationErrors(errors); return; }

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];
    let pIndex = 0; let rIndex = 0;

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      const isRoomFree = (num) => !globalSchedule.some(gs => gs.room === num && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));
      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];

      const getFreeProctors = (pool) => pool.filter(p => dayDate >= p.dayStart && dayDate <= p.dayEnd && startTime >= p.timeStart && endTime <= p.timeEnd && !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time)));
      let availableProctors = getFreeProctors(proctorSource === "Department" ? proctors : globalProctorPool);
      if (availableProctors.length === 0 && proctorSource === "Department") availableProctors = getFreeProctors(globalProctorPool);

      if (availableRooms.length < sectionCount) {
        errors.push({ issue: `Room Deficit (Day ${d+1})`, resolution: `Conflict detected. Required: ${sectionCount}. Available: ${availableRooms.length}.` });
      }
      if (availableProctors.length < sectionCount) {
        errors.push({ issue: `Staff Shortage (Day ${d+1})`, resolution: `Critical staff overlap. Required: ${sectionCount}. Found: ${availableProctors.length}.` });
      }

      if (errors.length > 0) break;

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;
        const selectedRoom = availableRooms[rIndex % availableRooms.length];
        const selectedProctor = availableProctors[pIndex % availableProctors.length];

        daySubjects.forEach((sub, idx) => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID, year_level: selectedYear,
            dept_code: deptCode, exam_date: dayDate, start_time: addHours(startTime, idx),
            end_time: addHours(startTime, idx + 1), room: selectedRoom.number, proctor: selectedProctor.name, status: 'ACTIVE'
          });
        });
        pIndex++; rIndex++;
      }
    }

    if (errors.length > 0) { setGenerationErrors(errors); return; }
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  return (
    <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden mb-16">
      {/* HEADER SECTION */}
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center relative">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 to-emerald-500"></div>
        <div>
          <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none">{deptName}</h2>
          <p className="text-blue-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Workspace Engine</p>
        </div>
        <button onClick={() => { onClearSchedule(deptCode); onDeleteDept(deptId, deptCode); }} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
          <Trash2 size={20}/>
        </button>
      </div>

      {/* NAVIGATION TABS */}
      <div className="flex bg-slate-50/50 p-3 gap-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400 hover:bg-slate-100'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-12">
        {activeTab === 'subjects' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-slate-50 p-6 rounded-[2rem]">
              <select className="p-4 rounded-xl text-xs font-black" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-4 rounded-xl text-xs font-black border" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-4 rounded-xl text-xs font-black border" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value;
                const n = document.getElementById(`sN-${deptId}`).value;
                if (c && n) {
                  onUpdate('subjects', { ...subjects, [selectedYear]: [...(subjects[selectedYear] || []), { code: c.toUpperCase(), name: n }] });
                  document.getElementById(`sC-${deptId}`).value = ''; document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase">Add Subject</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="p-4 border rounded-2xl flex justify-between items-center bg-white shadow-sm">
                  <span className="font-black text-xs">{s.code} - {s.name}</span>
                  <Trash2 size={16} className="text-rose-500 cursor-pointer" onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })} />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'proctors' && (
          <div className="space-y-6">
            <div className="bg-emerald-50/50 p-6 rounded-[2rem] grid grid-cols-1 md:grid-cols-2 gap-4">
              <input value={pName} onChange={e => setPName(e.target.value)} placeholder="STAFF NAME" className="p-4 rounded-xl text-xs font-black border" />
              <div className="flex gap-2">
                <input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="flex-1 p-4 rounded-xl text-xs border" />
                <input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="flex-1 p-4 rounded-xl text-xs border" />
              </div>
              <div className="flex gap-2">
                <input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="flex-1 p-4 rounded-xl text-xs border" />
                <input type="time" value={pTimeEnd} onChange={e => setPTimeEnd(e.target.value)} className="flex-1 p-4 rounded-xl text-xs border" />
              </div>
              <button onClick={() => {
                if (pName && pDayStart && pDayEnd) {
                  onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: pTimeEnd }]);
                  setPName("");
                }
              }} className="bg-emerald-600 text-white rounded-xl font-black text-[10px] uppercase">Register Staff</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {proctors.map(p => (
                <div key={p.id} className="p-4 border rounded-2xl flex justify-between items-center bg-white">
                  <div className="text-[10px] font-black uppercase">
                    <p>{p.name}</p>
                    <p className="text-slate-400">{p.dayStart} to {p.dayEnd}</p>
                  </div>
                  <Trash2 size={16} className="text-rose-500 cursor-pointer" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'rooms' && (
          <div className="space-y-6">
            <div className="bg-amber-50/50 p-6 rounded-[2rem] flex gap-4">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM NO." className="flex-1 p-4 rounded-xl text-xs font-black border" />
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: roomType }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-8 rounded-xl font-black text-[10px] uppercase">Add Room</button>
            </div>
            <div className="grid grid-cols-3 md:grid-cols-6 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-4 border rounded-2xl text-center bg-white relative group">
                  <span className="font-black text-xl">{r.number}</span>
                  <Trash2 size={14} className="absolute top-2 right-2 text-rose-500 opacity-0 group-hover:opacity-100 cursor-pointer" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'generate' && (
          <ScheduleGenerator 
            examDays={examDays} examDates={examDates} setExamDates={setExamDates} 
            handleExamDayChange={handleExamDayChange} startTime={startTime} setStartTime={setStartTime}
            selectedYear={selectedYear} setSelectedYear={setSelectedYear} sectionCount={sectionCount}
            setSectionCount={setSectionCount} proctorSource={proctorSource} setProctorSource={setProctorSource}
            roomSource={roomSource} setRoomSource={setRoomSource} onGenerate={handleGenerateClick}
            generationErrors={generationErrors} deptCode={deptCode} globalSchedule={globalSchedule}
          />
        )}

        {activeTab === 'preview' && (
          <div className="space-y-12">
            <div className="flex justify-between items-center border-b pb-6">
              <h3 className="text-3xl font-black uppercase italic">Draft Preview</h3>
              <button onClick={() => onClearSchedule(deptCode)} className="text-rose-500 text-[10px] font-black uppercase tracking-widest hover:underline">Wipe All</button>
            </div>

            <GlobalOverview tablesByYearAndDay={tablesByYearAndDay} />

            <div className="space-y-6">
              <h4 className="text-lg font-black uppercase text-slate-400 tracking-widest">iOS Style List View</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {consolidatedPreview.map((row, i) => (
                  <div key={i} className="bg-white rounded-3xl p-6 border-l-[12px] border-blue-500 shadow-xl hover:shadow-2xl transition-all relative group border-y border-r border-slate-100">
                    <div className="absolute top-6 right-6 flex gap-2">
                        <button onClick={() => handleExportPDF(row)} className="p-2 bg-emerald-50 text-emerald-600 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-emerald-600 hover:text-white">
                          <FileText size={16} />
                        </button>
                        <button onClick={() => onClearSchedule(deptCode, row.year, row.section, row.date)} className="p-2 bg-rose-50 text-rose-500 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-rose-500 hover:text-white">
                          <Trash2 size={16} />
                        </button>
                    </div>

                    <div className="mb-4">
                      <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Year {row.year}</span>
                      <h5 className="text-3xl font-black text-slate-900 tracking-tighter">{row.section}</h5>
                    </div>

                    <div className="space-y-3 mb-6">
                      <div className="flex items-center gap-3 text-slate-500">
                        <Calendar size={14} />
                        <span className="text-[11px] font-black uppercase tracking-tight">{row.date}</span>
                      </div>
                      <div className="flex items-center gap-3 text-slate-500">
                        <Clock size={14} />
                        <span className="text-[11px] font-black uppercase tracking-tight">{formatTime(row.startTime)} - {formatTime(row.endTime)}</span>
                      </div>
                      <div className="flex items-center gap-3 text-slate-500">
                        <MapPin size={14} />
                        <span className="text-[11px] font-black uppercase tracking-tight">Room {row.room}</span>
                      </div>
                      <div className="flex items-center gap-3 text-slate-500">
                        <Users size={14} />
                        <span className="text-[11px] font-black uppercase tracking-tight truncate">{row.proctor}</span>
                      </div>
                    </div>

                    <div className="pt-4 border-t border-slate-50">
                      <p className="text-[9px] font-black text-slate-400 uppercase mb-2">Subjects Assigned</p>
                      <div className="flex flex-wrap gap-2">
                        {row.subs.map((s, idx) => (
                          <span key={idx} className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[9px] font-black">{s.code}</span>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
